import re
from urllib.parse import urlparse

def validate_url(url):
    try:
        result = urlparse(url)
        if all([result.username, result.password]):
            username = result.username.replace('%', '%25')
            password = result.password.replace('%', '%25')
            encoded_url = url.replace(result.username + ':' + result.password, username + ':' + password)
            if encoded_url == url:
                print("Invalid URL: Username and/or password not properly encoded.")
                return False
        return True
    except ValueError:
        print("Invalid URL format.")
        return False

if __name__ == "__main__":
    test_urls = [
        "http://foo/bar@example.com",
        "http://user:pass@domain.com/path?query=value"
    ]

    for url in test_urls:
        if not validate_url(url):
            exit(1)
    exit(0)
